function addPdvProduct(product){const existing=pdvCart.find(x=>x.id===product.id);if(existing)existing.qty=Math.min(existing.qty+1,Number(product.estoque));else pdvCart.push({id:product.id,nome:product.nome,valorVenda:Number(product.valorVenda),qty:1})}
function pdvPage(){const query=pdvQuery.trim().toLowerCase();const products=db.produtos.filter(x=>Number(x.estoque)>0&&(!query||x.nome.toLowerCase().includes(query)||String(x.sku||'').toLowerCase().includes(query)));const total=pdvCart.reduce((s,item)=>s+item.qty*Number(item.valorVenda),0);return `<div class="page-head"><div><div class="eyebrow">Vendas presenciais</div><h1>PDV</h1><p>Registre compras realizadas no balcão e finalize a venda rapidamente.</p></div><button class="btn secondary" data-page-link="dashboard">← Voltar ao dashboard</button></div><div class="pdv-layout"><section class="card pdv-products"><div class="panel-head"><div><h2>Produtos disponíveis</h2><small>Busque pelo nome, SKU ou leia o código de barras.</small></div></div><div class="pdv-search"><input id="pdvSearch" value="${escapeHtml(pdvQuery)}" placeholder="⌕ Nome ou código do produto..." aria-label="Pesquisar produto por nome ou código"><button type="button" class="pdv-scan" data-pdv-scan-open><span>▣</span> Ler código</button></div><small class="pdv-scan-help">A câmera captura automaticamente assim que identificar um código.</small><div class="pdv-product-grid">${products.length?products.map(p=>`<button class="pdv-product" data-pdv-add="${p.id}"><strong>${escapeHtml(p.nome)}</strong><small>${escapeHtml(p.sku||'Sem código')} · ${p.estoque} un. disponíveis</small><b>${money(p.valorVenda)}</b></button>`).join(''):'<div class="filter-empty">Nenhum produto encontrado.</div>'}</div></section><section class="card pdv-cart"><div class="panel-head"><div><h2>Carrinho</h2><small>${pdvCart.reduce((s,x)=>s+x.qty,0)} item(ns)</small></div><button class="btn secondary" data-pdv-clear>Limpar</button></div>${pdvCart.length?pdvCart.map(item=>`<div class="pdv-cart-item"><div><strong>${escapeHtml(item.nome)}</strong><small>${money(item.valorVenda)} cada</small></div><div class="pdv-qty"><button data-pdv-qty="${item.id}:-1">−</button><span>${item.qty}</span><button data-pdv-qty="${item.id}:1">＋</button></div><b>${money(item.qty*Number(item.valorVenda))}</b></div>`).join(''):'<div class="filter-empty">Nenhum item adicionado.</div>'}<div class="pdv-total"><span>Total</span><strong>${money(total)}</strong></div><button class="btn primary pdv-finish" data-pdv-finish ${pdvCart.length?'':'disabled'}>Finalizar venda</button></section></div>`}
let pdvScannerStream=null;let pdvScannerFrame=null;
function closePdvScanner(){if(pdvScannerFrame)cancelAnimationFrame(pdvScannerFrame);pdvScannerFrame=null;if(pdvScannerStream){pdvScannerStream.getTracks().forEach(track=>track.stop());pdvScannerStream=null}document.getElementById('pdvScanner')?.remove()}
async function startPdvScanner(){if(!('BarcodeDetector'in window)){showToast('Este navegador não oferece leitura automática de códigos. Use a busca por nome ou SKU.');return}if(!navigator.mediaDevices?.getUserMedia){showToast('A câmera não está disponível neste dispositivo.');return}closePdvScanner();const overlay=document.createElement('div');overlay.id='pdvScanner';overlay.className='pdv-scanner-backdrop';overlay.innerHTML='<div class="pdv-scanner-modal"><div class="pdv-scanner-head"><strong>Ler código de barras</strong><button type="button" class="modal-close" data-pdv-scan-close>×</button></div><div class="pdv-scanner-view"><video autoplay playsinline muted></video><div class="pdv-scanner-guide"></div></div><small>Aponte a câmera para o código. A captura será automática.</small></div>';document.body.appendChild(overlay);overlay.querySelector('[data-pdv-scan-close]').onclick=closePdvScanner;try{pdvScannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});const video=overlay.querySelector('video');video.srcObject=pdvScannerStream;await video.play();const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128','code_39','itf']});const detect=async()=>{if(!document.body.contains(overlay))return;try{const codes=await detector.detect(video);const code=codes[0]?.rawValue;if(code){closePdvScanner();const product=db.produtos.find(x=>String(x.sku||'').toLowerCase()===code.toLowerCase()||String(x.codigo||'').toLowerCase()===code.toLowerCase());if(product&&Number(product.estoque)>0){addPdvProduct(product);pdvQuery='';showToast(`${product.nome} adicionado ao carrinho.`)}else{pdvQuery=code;showToast(`Código ${code} lido. Nenhum produto correspondente foi localizado.`)}render('pdv');return}}catch{}pdvScannerFrame=requestAnimationFrame(detect)};pdvScannerFrame=requestAnimationFrame(detect)}catch{closePdvScanner();showToast('Não foi possível acessar a câmera. Verifique a permissão do navegador.')}}
document.addEventListener('click',e=>{const add=e.target.closest('[data-pdv-add]');if(add){const p=db.produtos.find(x=>x.id===Number(add.dataset.pdvAdd));if(!p)return;addPdvProduct(p);render('pdv');return}const qty=e.target.closest('[data-pdv-qty]');if(qty){const [id,delta]=qty.dataset.pdvQty.split(':').map(Number);const item=pdvCart.find(x=>x.id===id);if(item){item.qty+=delta;if(item.qty<=0)pdvCart=pdvCart.filter(x=>x.id!==id);render('pdv')}return}if(e.target.closest('[data-pdv-clear]')){pdvCart=[];render('pdv');return}if(e.target.closest('[data-pdv-finish]')&&pdvCart.length){const total=pdvCart.reduce((s,item)=>s+item.qty*Number(item.valorVenda),0);checkpoint();pdvCart.forEach(item=>{const product=db.produtos.find(x=>x.id===item.id);if(product)product.estoque=Math.max(0,Number(product.estoque)-item.qty)});db.pedidos.unshift({id:Math.max(1000,...db.pedidos.map(x=>x.id))+1,comprador:'Venda presencial',emissao:new Date().toISOString().slice(0,10),valor:total,status:'Faturado',editadoPor:'Lucas Almeida',editadoEm:new Date().toISOString().slice(0,10)});saveData();pdvCart=[];showToast(`Venda presencial registrada: ${money(total)}.`);render('dashboard')}});
