function field(key,label,type='text'){return {key,label,type,required:true}}
function optionalField(key,label,type='text'){return {key,label,type,required:false}}
function select(key,label,options){return {key,label,type:'select',options,required:true}}
function selectDynamic(key,label,source){return {key,label,type:'select',source,required:true}}
function clone(value){return JSON.parse(JSON.stringify(value))}
function loadData(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(!saved?.produtos)return clone(seed);const hydrated={...clone(seed),...saved};for(const type of Object.keys(seed)){if(!Array.isArray(hydrated[type]))continue;hydrated[type]=hydrated[type].map(item=>({...seed[type].find(x=>x.id===item.id),...item}))}hydrated.configuracoes={...seed.configuracoes,...hydrated.configuracoes};hydrated.produtos=hydrated.produtos.map(item=>({...item,valorCompra:Number(item.valorCompra??0),valorVenda:Number(item.valorVenda??item.preco??0),markup:item.markup===''||item.markup===null||item.markup===undefined?null:Number(item.markup)}));if(hydrated.faturas.some(x=>['Cloud Serviços','Conecta Telecom','Energia Sul'].includes(x.fornecedor)))hydrated.faturas=clone(seed.faturas);return hydrated}catch{return clone(seed)}}
function saveData(){localStorage.setItem(STORAGE_KEY,JSON.stringify(db))}
function money(value){return Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function compactMoney(value){const number=Number(value||0);if(Math.abs(number)>=1000000)return `R$ ${(number/1000000).toLocaleString('pt-BR',{maximumFractionDigits:1})} mi`;if(Math.abs(number)>=1000)return `R$ ${(number/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})} mil`;return money(number).replace(/,00$/,'')}
function datePt(value){if(!value)return '—';return new Date(`${value}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}
function badgeClass(status){return ['Ativo','Aceito','Faturado','Nota emitida','Enviado'].includes(status)?'green':['Estoque baixo','Em análise','A faturar','Orçamento Aprovado','Convite pendente'].includes(status)?'amber':['Sem estoque','Estoque incorreto','Expirado'].includes(status)?'red':status==='Separação'?'blue':''}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}

function render(page=currentPage,options={}){const scrollTop=window.scrollY;currentPage=page;filterState={query:'',status:'Todos os status',order:'Mais recentes',dateFrom:'',dateTo:''};document.getElementById('content').innerHTML=page==='dashboard'?dashboard():page==='pdv'?pdvPage():page==='fluxo'?commercialFlow():page==='configuracoes'?settingsPage():page==='orcamentos'?openQuotesPage():page==='faturados'?orderSubset('Faturado'):page==='enviados'?shippingPage():listing(page);document.querySelectorAll('.nav-item,.nav-subitem').forEach(x=>x.classList.toggle('active',x.dataset.page===page));const partnersToggle=document.querySelector('[data-partners-toggle]');const partnersSubmenu=document.getElementById('partnersSubmenu');if(partnersToggle&&partnersSubmenu&&(page==='fornecedores'||page==='transportadoras')){partnersToggle.classList.add('active');partnersToggle.setAttribute('aria-expanded','true');partnersToggle.closest('.nav-group')?.classList.add('open')}const flowBadge=document.querySelector('[data-page="fluxo"] b');if(flowBadge)flowBadge.textContent=db.orcamentos.length+db.pedidos.length;bindPage();updateNotifications();document.getElementById('sidebar').classList.remove('open');window.scrollTo({top:options.preserveScroll?scrollTop:0,behavior:options.preserveScroll?'auto':'smooth'})}
function ticketOrders(){const orders=db.pedidos.filter(x=>x.emissao);if(ticketPeriod==='30d'){const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-29);return orders.filter(x=>new Date(`${x.emissao}T00:00:00`)>=cutoff)}return orders.filter(x=>String(x.emissao).slice(0,7)===ticketMonth)}
function ticketKpi(){const orders=ticketOrders();const average=orders.length?orders.reduce((s,x)=>s+Number(x.valor),0)/orders.length:0;return `<section class="card kpi ticket-kpi" data-tooltip="Valor médio por pedido no período selecionado."><div class="kpi-top"><span>Ticket médio</span><span class="kpi-icon">◇</span></div><strong>${money(average)}</strong><span class="trend">${orders.length} pedidos no período</span><div class="ticket-controls"><button type="button" class="ticket-period ${ticketPeriod==='30d'?'active':''}" data-ticket-period="30d">Últimos 30 dias</button><button type="button" class="ticket-period ${ticketPeriod==='month'?'active':''}" data-ticket-period="month" data-ticket-month-trigger>Mês selecionado</button><input type="month" value="${ticketMonth}" aria-label="Selecionar mês do ticket médio" data-ticket-month></div></section>`}
function dashboard(){const open=db.orcamentos.filter(x=>!['Aceito','Expirado'].includes(x.status));const billed=db.pedidos.filter(x=>x.status==='Faturado');const shipped=db.pedidos.filter(x=>x.status==='Enviado');const billedTotal=billed.reduce((s,x)=>s+Number(x.valor),0);return `<div class="page-head"><div><div class="eyebrow">Visão geral</div><h1>Bom dia, Lucas!</h1><p>Os indicadores abaixo refletem as alterações feitas neste protótipo.</p></div><div class="dashboard-actions"><button class="btn secondary" data-page-link="pdv">▣ Abrir PDV</button><button class="btn primary" data-add="orcamentos">＋ Novo orçamento</button></div></div><div class="kpi-grid">${kpi('Orçamentos em aberto',money(open.reduce((s,x)=>s+Number(x.valor),0)),`${open.length} propostas ativas`,'▤')}${kpi('Faturado',money(billedTotal),`${billed.length} notas emitidas`,'✓')}${kpi('Pedidos para envio',db.pedidos.filter(x=>x.status!=='Enviado').length,`${shipped.length} já enviados`,'↗','neutral')}${ticketKpi()}</div><div class="dashboard-grid"><div class="card panel"><div class="panel-head"><div><h2>Valores por etapa</h2><small>${dashboardStage===null?'Atualizado com os dados locais':'Clique em outra barra para comparar etapas'}</small></div></div><div class="chart">${chartBars()}</div><div class="chart-labels"><span>Orç.</span><span>Orçamento aprovado</span><span>Nota emitida</span><span>Nota emitida</span><span>Enviado</span></div></div><div class="card panel">${dashboardSidePanel()}</div><div class="card panel activities"><div class="panel-head"><div><h2>Atividades recentes</h2><small>Últimos registros comerciais</small></div><button class="btn secondary" data-page-link="fluxo">Abrir fluxo</button></div>${activityTable()}</div></div>`}
function dashboardSidePanel(){if(dashboardStage===null)return `<div class="panel-head"><div><h2>Pedidos por status</h2><small>${db.pedidos.length} pedidos cadastrados</small></div></div><div class="status-list">${['Rascunho','A faturar','Faturado','Enviado'].map((s,i)=>status(s,db.pedidos.filter(x=>x.status===s).length,db.pedidos.length,i)).join('')}</div>`;if(dashboardStage===0){const statuses=['Rascunho','Enviado','Em análise','Aceito'];return `<div class="panel-head"><div><h2>Orçamentos por status</h2><small>${db.orcamentos.length} propostas cadastradas</small></div><button class="panel-clear" data-clear-stage>Limpar</button></div><div class="status-list">${statuses.map((s,i)=>status(s,db.orcamentos.filter(x=>x.status===s).length,db.orcamentos.length,i)).join('')}</div>`}const stageNames=['','A faturar','Separação','Faturado','Enviado'];const name=stageNames[dashboardStage];const items=db.pedidos.filter(x=>x.status===name);return `<div class="panel-head"><div><h2>Pedidos · ${orderStatusLabel(name)}</h2><small>${items.length} pedido(s) nesta etapa</small></div><button class="panel-clear" data-clear-stage>Limpar</button></div><div class="stage-items">${items.length?items.map(x=>`<button class="stage-item" data-stage-order="${x.id}"><span><strong>#${x.id}</strong><small>${escapeHtml(x.comprador)}</small></span><b>${money(x.valor)}</b></button>`).join(''):'<div class="filter-empty">Nenhum pedido nesta etapa.</div>'}</div>`}
function kpi(label,value,trend,icon,cls='',page=''){const target=page||({'Orçamentos em aberto':'orcamentos','Faturado':'faturados','Pedidos para envio':'enviados','Ticket médio':'pedidos'}[label]||'');const visibleLabel=label==='Faturado'?'Nota emitida':label;const descriptions={'Orçamentos em aberto':'Soma dos valores de propostas que ainda não foram aceitas ou expiradas.','Faturado':'Valor total dos pedidos que já possuem a nota emitida.','Pedidos para envio':'Quantidade de pedidos que ainda não foram enviados ao cliente.','Ticket médio':'Valor médio por pedido, calculado sobre todos os pedidos cadastrados.'};const description=descriptions[label]||label;return `<button class="card kpi ${target?'kpi-link':''}" ${target?`data-page-link="${target}"`:''} data-tooltip="${description}" aria-label="${visibleLabel}. ${description}"><span class="kpi-top"><span>${visibleLabel}</span><span class="kpi-icon">${icon}</span></span><strong>${value}</strong><span class="trend ${cls}">${trend}</span></button>`}
function chartBars(){const values=[db.orcamentos.reduce((s,x)=>s+Number(x.valor),0),...['A faturar','Separação','Faturado','Enviado'].map(st=>db.pedidos.filter(x=>x.status===st).reduce((s,x)=>s+Number(x.valor),0))];const max=Math.max(...values,1);return values.map((v,i)=>{const height=Math.max(5,v/max*78);const current=dashboardStage===null?i===3:dashboardStage===i;return `<button class="bar-wrap ${dashboardStage===i?'selected':''}" data-dashboard-stage="${i}" style="--bar-height:${height}%" title="${money(v)}"><span class="bar-value">${compactMoney(v)}</span><i class="bar ${current?'current':''}" style="height:${height}%"></i></button>`}).join('')}
function status(label,count,total,index){const colors=['amber','blue','green','slate'];return `<div class="status-row"><i class="dot ${colors[index]}"></i><span>${orderStatusLabel(label)}</span><strong>${count}</strong><div class="progress"><i style="width:${total?count/total*100:0}%"></i></div></div>`}
function activityTable(){const rows=[...db.pedidos].sort((a,b)=>b.id-a.id).slice(0,4);return rows.length?`<table class="activity-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Emissão</th><th>Valor</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>#${x.id}</strong></td><td>${escapeHtml(x.comprador)}</td><td>${datePt(x.emissao)}</td><td>${money(x.valor)}</td><td><span class="badge ${badgeClass(x.status)}">${escapeHtml(orderStatusLabel(x.status))}</span></td></tr>`).join('')}</tbody></table>`:'<div class="filter-empty">Nenhum pedido cadastrado.</div>'}
function commercialFlow(){const query=flowSearch.trim().toLocaleLowerCase('pt-BR');const byStore=items=>query?items.filter(x=>x.comprador.toLocaleLowerCase('pt-BR').includes(query)):items;const columns=[
  {key:'orcamentos',title:'Orçamentos',subtitle:'Propostas comerciais',icon:'▤',items:byStore(db.orcamentos),type:'orcamentos'},
  {key:'pedidos',title:'Pedidos',subtitle:'Orçamentos aprovados e notas emitidas',icon:'◫',items:byStore(db.pedidos.filter(x=>['Rascunho','A faturar','Separação'].includes(x.status))),type:'pedidos'},
  {key:'faturados',title:'Nota emitida',subtitle:'Documento fiscal emitido',icon:'✓',items:byStore(db.pedidos.filter(x=>x.status==='Faturado')),type:'pedidos'},
  {key:'enviados',title:'Enviados',subtitle:'Despachados ao cliente',icon:'↗',items:byStore(db.pedidos.filter(x=>x.status==='Enviado')),type:'pedidos'}
];const total=columns.reduce((s,c)=>s+c.items.length,0);const visibleQuotes=columns[0].items;const visibleOrders=columns.slice(1).flatMap(x=>x.items);const stores=[...new Set([...db.compradores.map(x=>x.nome),...db.orcamentos.map(x=>x.comprador),...db.pedidos.map(x=>x.comprador)])].sort();return `<div class="page-head"><div><div class="eyebrow">Comercial</div><h1>Fluxo comercial</h1><p>Acompanhe cada negociação do orçamento até o envio em uma única visão.</p></div><button class="btn primary" data-add="orcamentos">＋ Novo orçamento</button></div><div class="store-search card"><span>⌕</span><div><label for="storeSearch">Pesquisar loja</label><input id="storeSearch" list="storeOptions" placeholder="Digite o nome da loja para ver todo o histórico..." value="${escapeHtml(flowSearch)}" autocomplete="off"><datalist id="storeOptions">${stores.map(x=>`<option value="${escapeHtml(x)}"></option>`).join('')}</datalist></div>${flowSearch?'<button data-clear-store aria-label="Limpar busca">×</button>':''}</div><div class="flow-summary"><div><small>${query?'REGISTROS ENCONTRADOS':'REGISTROS NO FLUXO'}</small><strong>${total}</strong></div><div><small>VALOR EM ORÇAMENTOS</small><strong>${money(visibleQuotes.reduce((s,x)=>s+Number(x.valor),0))}</strong></div><div><small>VALOR EM PEDIDOS</small><strong>${money(visibleOrders.reduce((s,x)=>s+Number(x.valor),0))}</strong></div><button class="btn secondary reset-button" data-reset>Restaurar dados</button></div><div class="flow-board">${columns.map((c,i)=>flowColumn(c,i)).join('')}</div><p class="flow-hint">Clique para editar ou arraste para mudar de etapa · Ctrl+Z desfaz · Ctrl+Y refaz</p>`}
function flowColumn(column,index){const value=column.items.reduce((s,x)=>s+Number(x.valor),0);return `<section class="flow-column stage-${index}" data-flow-stage="${index}"><header><div class="flow-title"><span>${column.icon}</span><div><h2>${column.title}</h2><small>${column.subtitle}</small></div></div><div class="flow-count">${column.items.length}</div></header><div class="flow-total">Total <strong>${money(value)}</strong></div><div class="flow-cards">${column.items.length?column.items.map(item=>flowCard(column,item,index)).join(''):`<div class="flow-empty"><span>${column.icon}</span><p>Nenhum registro nesta etapa</p></div>`}</div>${index<2?`<button class="flow-add" data-add="${column.type}">＋ Adicionar em ${column.title.toLowerCase()}</button>`:''}</section>`}
function flowCard(column,item,index){const dateValue=column.type==='orcamentos'?item.validade:item.emissao;return `<article class="flow-card" draggable="true" data-flow-edit="${column.type}:${item.id}" data-flow-origin="${index}" tabindex="0" title="Clique para editar ou arraste para outra etapa"><div class="flow-drag-handle" aria-hidden="true">⠿</div><div class="flow-card-top"><span class="flow-code">#${item.id}</span><span class="badge ${badgeClass(item.status)}">${escapeHtml(column.type==='pedidos'?orderStatusLabel(item.status):item.status)}</span></div><h3>${escapeHtml(item.comprador)}</h3><div class="flow-card-value">${money(item.valor)}</div><div class="flow-card-meta"><span>${column.type==='orcamentos'?'Validade':'Emissão'}</span><strong>${datePt(dateValue)}</strong></div><div class="flow-card-actions"><button class="flow-delete" data-delete="${column.type}:${item.id}" title="Excluir">⌫</button>${index<3?`<button class="flow-next" data-advance="${column.type}:${item.id}:${index}">Avançar <span>→</span></button>`:'<span class="flow-complete">Fluxo concluído ✓</span>'}</div></article>`}
function listing(type,subset){const config=configs[type];if(!config)return emptyPage('Configurações','As preferências serão implementadas após a validação do protótipo.','⚙');const data=filtered(type,subset);const all=subset?db[type].filter(subset):db[type];const searchPlaceholder=type==='pedidos'?'⌕  Pesquisar por nome do cliente...':`⌕  Pesquisar em ${config.title.toLowerCase()}...`;const backButton=type==='pedidos'?'<button class="btn secondary" data-page-link="dashboard">← Voltar ao dashboard</button> ':'';const dateFilters=type==='pedidos'?`<label class="date-filter"><span>De</span><input id="dateFromFilter" type="date" value="${filterState.dateFrom}" aria-label="Data inicial"></label><label class="date-filter"><span>Até</span><input id="dateToFilter" type="date" value="${filterState.dateTo}" aria-label="Data final"></label>`:'';const statusValues=type==='pedidos'?orderStatusOptions:[...new Set(all.map(x=>x.status).filter(Boolean))];const statusOptions=statusValues.map(s=>`<option value="${escapeHtml(s)}" ${filterState.status===s?'selected':''}>${escapeHtml(type==='pedidos'?s:s)}</option>`).join('');return `<div class="page-head"><div><div class="eyebrow">Gestão</div><h1>${config.title}</h1><p>${config.desc}</p></div><div>${backButton}<button class="btn secondary reset-button" data-reset>Restaurar dados</button> <button class="btn primary" data-add="${type}">＋ ${config.action}</button></div></div><div class="card table-card"><div class="filters"><div class="search"><input id="tableSearch" aria-label="Pesquisar por nome do cliente" placeholder="${searchPlaceholder}" value="${escapeHtml(filterState.query)}"></div>${dateFilters}<select id="statusFilter"><option value="Todos os status">Todos os status</option>${statusOptions}</select><select id="orderFilter"><option>Mais recentes</option><option ${filterState.order==='Nome A–Z'?'selected':''}>Nome A–Z</option></select></div><div class="summary-strip"><span>Registros <strong>${data.length}</strong></span><span>Total cadastrado <strong>${all.length}</strong></span></div><div class="table-scroll">${table(type,data)}</div><div class="table-footer"><span>Mostrando ${data.length} de ${all.length} registros</span><div class="pagination"><button>‹</button><button class="active">1</button><button>›</button></div></div></div>`}
function openQuotesPage(){const companies=[...new Set(db.orcamentos.map(x=>x.comprador))].sort();const rows=db.orcamentos.filter(x=>!['Aceito','Expirado'].includes(x.status)).filter(x=>{const days=x.validade?daysUntil(x.validade):null;const matchesDays=quoteFilters.days==='all'||(quoteFilters.days==='none'&&!x.validade)||(quoteFilters.days==='expired'&&days<0)||(quoteFilters.days==='today'&&days===0)||(quoteFilters.days==='short'&&days>=1&&days<=3)||(quoteFilters.days==='medium'&&days>=4&&days<=7)||(quoteFilters.days==='long'&&days>=8&&days<=30);const matchesCompany=quoteFilters.company==='all'||x.comprador===quoteFilters.company;const matchesId=!quoteFilters.id||String(x.id).includes(quoteFilters.id);return matchesDays&&matchesCompany&&matchesId});return `<div class="page-head"><div><div class="eyebrow">Comercial</div><h1>Orçamentos em aberto</h1><p>Consulte propostas abertas e acompanhe o prazo restante para invalidação.</p></div><div><button class="btn secondary" data-page-link="dashboard">← Voltar ao dashboard</button> <button class="btn primary" data-add="orcamentos">＋ Novo orçamento</button></div></div><div class="card table-card quote-list-card"><div class="filters quote-filters"><select id="quoteDaysFilter"><option value="all" ${quoteFilters.days==='all'?'selected':''}>Dias para invalidação: todos</option><option value="expired" ${quoteFilters.days==='expired'?'selected':''}>Já invalidados</option><option value="today" ${quoteFilters.days==='today'?'selected':''}>Invalida hoje</option><option value="short" ${quoteFilters.days==='short'?'selected':''}>1 a 3 dias</option><option value="medium" ${quoteFilters.days==='medium'?'selected':''}>4 a 7 dias</option><option value="long" ${quoteFilters.days==='long'?'selected':''}>8 a 30 dias</option><option value="none" ${quoteFilters.days==='none'?'selected':''}>Sem validade</option></select><select id="quoteCompanyFilter"><option value="all">Todas as empresas</option>${companies.map(x=>`<option value="${escapeHtml(x)}" ${quoteFilters.company===x?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select><div class="search"><input id="quoteIdFilter" inputmode="numeric" placeholder="⌕  Buscar por ID" value="${escapeHtml(quoteFilters.id)}"></div></div><div class="summary-strip"><span>Orçamentos encontrados <strong>${rows.length}</strong></span><span>Valor total <strong>${money(rows.reduce((s,x)=>s+Number(x.valor),0))}</strong></span></div><div class="table-scroll">${quoteTable(rows)}</div><div class="table-footer"><span>${rows.length} orçamento(s) em aberto</span><button class="btn secondary" data-page-link="dashboard">← Voltar ao dashboard</button></div></div>`}
function quoteTable(rows){if(!rows.length)return '<div class="filter-empty">Nenhum orçamento corresponde aos filtros.</div>';return `<table class="data-table"><thead><tr><th>ID</th><th>Empresa</th><th>Validade</th><th>Dias para invalidação</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(x=>{const days=x.validade?daysUntil(x.validade):null;const label=days===null?'Sem validade':days<0?`Vencido há ${Math.abs(days)} d`:days===0?'Hoje':`${days} d`;return `<tr class="editable-row" data-row-edit="orcamentos:${x.id}" tabindex="0"><td><strong>#${x.id}</strong></td><td>${escapeHtml(x.comprador)}</td><td>${datePt(x.validade)}</td><td><span class="badge ${days!==null&&days<=3?'amber':''}">${label}</span></td><td><strong>${money(x.valor)}</strong></td><td><span class="badge ${badgeClass(x.status)}">${escapeHtml(x.status)}</span></td><td><div class="row-actions"><button class="action-button danger" title="Excluir" data-delete="orcamentos:${x.id}">⌫</button></div></td></tr>`}).join('')}</tbody></table>`}
function shippingPage(){const original=configs.pedidos;configs.pedidos={...original,title:'Pedidos para envio',desc:'Pedidos que ainda precisam ser separados, faturados ou despachados.',action:'Novo pedido'};const html=listing('pedidos',x=>x.status!=='Enviado');configs.pedidos=original;return html}
function orderSubset(statusName){const title=statusName==='Faturado'?'Itens com nota emitida':'Itens enviados';const desc=statusName==='Faturado'?'Pedidos cuja nota fiscal já foi emitida.':'Pedidos despachados para os clientes.';const original=configs.pedidos;configs.pedidos={...original,title,desc,action:'Novo pedido'};const html=listing('pedidos',x=>x.status===statusName);configs.pedidos=original;return html}
function filtered(type,subset){let rows=[...(subset?db[type].filter(subset):db[type])];const q=filterState.query.toLocaleLowerCase('pt-BR');if(q)rows=rows.filter(x=>Object.values(x).some(v=>String(v).toLocaleLowerCase('pt-BR').includes(q)));if(filterState.status!=='Todos os status')rows=rows.filter(x=>type==='pedidos'?orderStatusLabel(x.status)===filterState.status:x.status===filterState.status);if(type==='pedidos'&&filterState.dateFrom)rows=rows.filter(x=>x.emissao>=filterState.dateFrom);if(type==='pedidos'&&filterState.dateTo)rows=rows.filter(x=>x.emissao<=filterState.dateTo);if(filterState.order==='Nome A–Z')rows.sort((a,b)=>String(a.nome||a.comprador).localeCompare(String(b.nome||b.comprador),'pt-BR'));else rows.sort((a,b)=>Number(b.id)-Number(a.id));return rows}
function table(type,rows){const config=configs[type];if(!rows.length)return '<div class="filter-empty">Nenhum registro encontrado para os filtros informados.</div>';return `<table class="data-table"><thead><tr>${config.columns.map(c=>`<th>${c[1]}</th>`).join('')}<th>Ações</th></tr></thead><tbody>${rows.map(row=>`<tr class="editable-row" data-row-edit="${type}:${row.id}" tabindex="0" title="Clique na linha para editar">${config.columns.map(c=>`<td>${formatCell(type,row,c)}</td>`).join('')}<td><div class="row-actions"><button class="action-button danger" title="Excluir" data-delete="${type}:${row.id}">⌫</button></div></td></tr>`).join('')}</tbody></table>`}
function formatCell(type,row,column){const [key,,format]=column;const value=row[key];if(format==='money')return `<strong>${money(value)}</strong>`;if(format==='margin'){const amount=Number(row.valorVenda)-Number(row.valorCompra);const percent=Number(row.valorVenda)>0?amount/Number(row.valorVenda)*100:0;const tone=amount<0?'negative':amount===0?'neutral':'';return `<div class="margin-value ${tone}"><strong>${money(amount)}</strong><small>${percent.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})}%</small></div>`}if(format==='percent')return `${Number(value).toLocaleString('pt-BR')}%`;if(format==='date')return datePt(value);if(format==='badge')return `<span class="badge ${badgeClass(value)}">${escapeHtml(type==='pedidos'?orderStatusLabel(value):value)}</span>`;if(format==='code')return `<strong>#${value}</strong>`;if(format==='emailLink')return value?`<a class="contact-link email-link" href="mailto:${encodeURIComponent(value)}" title="Enviar e-mail para ${escapeHtml(value)}"><span>✉</span>${escapeHtml(value)}</a>`:'—';if(format==='whatsapp'){if(!value)return '—';const digits=String(value).replace(/\D/g,'');const international=digits.startsWith('55')?digits:`55${digits}`;return `<a class="contact-link whatsapp-link" href="https://wa.me/${international}" target="_blank" rel="noopener noreferrer" title="Conversar pelo WhatsApp"><span>◉</span>${escapeHtml(value)}</a>`}if(format==='stock')return `<div class="stock-control"><button data-stock="${type}:${row.id}:-1" aria-label="Diminuir estoque">−</button><span>${value} un.</span><button data-stock="${type}:${row.id}:1" aria-label="Aumentar estoque">＋</button></div>`;return key==='nome'?`<div class="product-name"><span class="product-icon">${type==='produtos'?'◇':'◫'}</span><span><strong>${escapeHtml(value)}</strong></span></div>`:escapeHtml(value)}
function emptyPage(title,desc,icon){return `<div class="page-head"><div><div class="eyebrow">Gestão</div><h1>${title}</h1><p>${desc}</p></div></div><div class="card empty-state"><div class="empty-icon">${icon}</div><h2>Área demonstrativa</h2><p>Esta área não altera dados nesta versão do protótipo.</p></div>`}
function settingsPage(){const c=db.configuracoes;return `<div class="page-head"><div><div class="eyebrow">Preferências</div><h1>Configurações de alertas</h1><p>Defina alertas, markup padrão e personalize as mensagens de contato.</p></div></div><div class="settings-grid single"><form class="card settings-card" id="notificationSettings"><div class="panel-head"><div><h2>Limites das notificações</h2><small>As mudanças recalculam os alertas imediatamente.</small></div></div><label>Cliente sem comprar há<input name="diasClienteSemCompra" type="number" min="1" value="${c.diasClienteSemCompra}" required><span class="field-suffix">dias</span><small>Alerta o responsável e oferece uma mensagem pronta para contato.</small></label><label>Orçamento sem retorno há<input name="diasOrcamentoSemRetorno" type="number" min="1" value="${c.diasOrcamentoSemRetorno}" required><span class="field-suffix">dias</span><small>Considera propostas enviadas ou em análise sem movimentação.</small></label><label>Antecedência de faturas de fornecedores<input name="diasAntecedenciaFatura" type="number" min="1" value="${c.diasAntecedenciaFatura}" required><span class="field-suffix">dias</span><small>Somente faturas vinculadas a fornecedores cadastrados. Faturas vencidas sempre geram alerta crítico.</small></label><label>Markup padrão para novos produtos<input name="markupPadrao" type="number" min="0" step="0.01" value="${c.markupPadrao??''}><span class="field-suffix">%</span><small>Opcional. Será preenchido automaticamente no cadastro de novos produtos e poderá ser alterado.</small></label><div class="settings-divider"></div><div class="panel-head message-heading"><div><h2>Mensagens padrão</h2><small>Use <code>&lt;nome&gt;</code> onde deseja inserir automaticamente o nome do cliente.</small></div></div><label>Mensagem para e-mail<textarea name="mensagemEmail" rows="6" required>${escapeHtml(c.mensagemEmail)}</textarea><small>Será usada ao escolher “Contatar por E-mail”.</small></label><label>Mensagem para WhatsApp<textarea name="mensagemWhatsApp" rows="4" required>${escapeHtml(c.mensagemWhatsApp)}</textarea><small>Será usada ao escolher “Contatar por WhatsApp”.</small></label><div class="template-example"><strong>Exemplo</strong><span>“Bom dia, <code>&lt;nome&gt;</code>, gostaria de apresentar o produto a seguir...”</span></div><button class="btn primary" type="submit">Salvar configurações</button></form></div><div class="permission-note"><span>🔒</span><p><strong>Notificações de edição por outros funcionários</strong><br>Somente administradores e gestores com permissão de auditoria podem visualizar quem editou um pedido.</p></div>`}
function daysSince(value){return Math.floor((startOfToday()-new Date(`${value}T00:00:00`))/86400000)}
function daysUntil(value){return Math.ceil((new Date(`${value}T00:00:00`)-startOfToday())/86400000)}
function startOfToday(){const d=new Date();return new Date(d.getFullYear(),d.getMonth(),d.getDate())}
function clientMessage(client){const template=client.comunicacao==='E-mail'?db.configuracoes.mensagemEmail:db.configuracoes.mensagemWhatsApp;return String(template||'').replace(/<nome>/gi,client.nome)}
function preferredContact(client,message){if(client.comunicacao==='E-mail')return `mailto:${encodeURIComponent(client.email)}?subject=${encodeURIComponent('Novidades para você')}&body=${encodeURIComponent(message)}`;const digits=String(client.telefone||'').replace(/\D/g,'');return `https://wa.me/${digits.startsWith('55')?digits:`55${digits}`}?text=${encodeURIComponent(message)}`}
function getNotifications(){const alerts=[];for(const p of db.produtos){if(Number(p.estoque)<0)alerts.push({id:`stock-error-${p.id}`,kind:'critical',icon:'!',title:'Estoque inconsistente',text:`${p.nome} está com ${p.estoque} unidades. Corrija o saldo antes de vender.`,route:'produtos'});else if(Number(p.estoque)===0)alerts.push({id:`stock-zero-${p.id}`,kind:'critical',icon:'◇',title:'Produto sem estoque',text:`${p.nome} está indisponível para novos pedidos.`,route:'produtos'});else if(p.estoqueMinimo!==null&&p.estoqueMinimo!==''&&Number(p.estoque)<=Number(p.estoqueMinimo))alerts.push({id:`stock-low-${p.id}`,kind:'warning',icon:'◇',title:'Estoque abaixo do mínimo',text:`${p.nome}: ${p.estoque} un. disponíveis; mínimo definido em ${p.estoqueMinimo}.`,route:'produtos'})}const supplierNames=new Set(db.fornecedores.map(x=>x.nome));for(const f of db.faturas.filter(x=>!x.paga&&supplierNames.has(x.fornecedor))){const days=daysUntil(f.vencimento);if(days<0)alerts.push({id:`invoice-overdue-${f.id}`,kind:'critical',icon:'$',title:'Fatura de fornecedor vencida',text:`${f.fornecedor}: ${f.descricao}, ${money(f.valor)}, venceu há ${Math.abs(days)} dia(s).`,route:'fornecedores'});else if(days<=db.configuracoes.diasAntecedenciaFatura)alerts.push({id:`invoice-due-${f.id}`,kind:'warning',icon:'$',title:'Fatura de fornecedor próxima do vencimento',text:`${f.fornecedor}: ${f.descricao}, ${money(f.valor)}, vence ${days===0?'hoje':`em ${days} dia(s)`}.`,route:'fornecedores'})}for(const c of db.compradores.filter(x=>x.ultimaCompra)){const days=daysSince(c.ultimaCompra);if(days>=db.configuracoes.diasClienteSemCompra){const message=clientMessage(c,days);alerts.push({id:`client-${c.id}`,kind:'info',icon:'♙',title:'Cliente sem comprar',text:`${c.nome} está há ${days} dias sem comprar. Última compra: ${datePt(c.ultimaCompra)}.`,contact:preferredContact(c,message),contactLabel:`Contatar por ${c.comunicacao}`,message})}}for(const q of db.orcamentos.filter(x=>['Enviado','Em análise'].includes(x.status)&&x.atualizadoEm)){const days=daysSince(q.atualizadoEm);if(days>=db.configuracoes.diasOrcamentoSemRetorno)alerts.push({id:`quote-${q.id}`,kind:'warning',icon:'▤',title:'Orçamento sem retorno',text:`#${q.id} de ${q.comprador} está há ${days} dias sem movimentação.`,route:'fluxo',store:q.comprador})}for(const o of db.pedidos.filter(x=>x.editadoPor&&x.editadoPor!=='Lucas Almeida'))alerts.push({id:`edited-${o.id}-${o.editadoEm}`,kind:'audit',icon:'✎',title:'Pedido editado por outro funcionário',text:`${o.editadoPor} editou o pedido #${o.id} de ${o.comprador}.`,route:'fluxo',store:o.comprador,restricted:true});return alerts}
function notificationCategory(alert){if(alert.id.startsWith('stock-'))return 'produtos';if(alert.id.startsWith('invoice-'))return 'faturas';if(alert.id.startsWith('client-'))return 'clientes';if(alert.id.startsWith('quote-'))return 'comercial';return 'auditoria'}
function updateNotifications(){const alerts=getNotifications();const buttons=document.getElementById('notificationButtons');buttons.innerHTML=notificationCategories.map(category=>{const categoryAlerts=alerts.filter(x=>notificationCategory(x)===category.key);const unread=categoryAlerts.filter(x=>!notificationRead.has(x.id)).length;return `<button class="notification-category ${activeNotificationCategory===category.key?'active':''}" data-notification-category="${category.key}" aria-label="${category.label}: ${unread} não lida(s)"><span>${category.icon}</span><em>${category.label}</em><b ${unread===0?'hidden':''}>${unread>99?'99+':unread}</b></button>`}).join('');const selected=alerts.filter(x=>notificationCategory(x)===activeNotificationCategory);document.getElementById('notificationPanel').innerHTML=notificationPanelHtml(selected,notificationCategories.find(x=>x.key===activeNotificationCategory)?.label||'Notificações')}
function notificationPanelHtml(alerts,title){return `<div class="notification-header"><div><strong>${title}</strong><small>${alerts.length} alerta(s) ativo(s)</small></div><button data-read-all>Marcar como lidas</button></div><div class="notification-list">${alerts.length?alerts.map(a=>`<article class="notification-item ${a.kind} ${notificationRead.has(a.id)?'read':''}" data-alert-id="${a.id}" ${a.route?`data-alert-route="${a.route}"`:''} ${a.store?`data-alert-store="${escapeHtml(a.store)}"`:''}><span class="notification-icon">${a.icon}</span><div><div class="notification-title"><strong>${a.title}</strong>${!notificationRead.has(a.id)?'<i></i>':''}</div><p>${escapeHtml(a.text)}</p>${a.contact?`<a href="${a.contact}" target="_blank" rel="noopener noreferrer">${a.contactLabel} →</a><details><summary>Ver mensagem pronta</summary><blockquote>${escapeHtml(a.message)}</blockquote></details>`:''}${a.restricted?'<small class="restricted">🔒 Visível somente para administradores e gestores autorizados.</small>':''}</div></article>`).join(''):'<div class="notifications-empty">✓<strong>Tudo em ordem</strong><span>Nenhum alerta ativo nesta categoria.</span></div>'}</div><div class="notification-footer"><button data-page-notifications="configuracoes">Configurar alertas</button></div>`}

function bindPage(){document.querySelectorAll('[data-add]').forEach(x=>x.onclick=()=>openForm(x.dataset.add));document.querySelectorAll('[data-ticket-period]').forEach(x=>x.onclick=()=>{ticketPeriod=x.dataset.ticketPeriod;if(x.hasAttribute('data-ticket-month-trigger')){const input=document.querySelector('[data-ticket-month]');input?.focus();try{input?.showPicker?.()}catch{}}else render('dashboard')});const ticketMonthInput=document.querySelector('[data-ticket-month]');if(ticketMonthInput){const useCurrentMonth=()=>{if(!ticketMonthInput.value){ticketMonth=new Date().toISOString().slice(0,7);ticketMonthInput.value=ticketMonth}};ticketMonthInput.addEventListener('change',e=>{ticketMonth=e.target.value||new Date().toISOString().slice(0,7);ticketPeriod='month';render('dashboard')});ticketMonthInput.addEventListener('blur',useCurrentMonth);ticketMonthInput.addEventListener('keydown',e=>{if(e.key==='Enter'){useCurrentMonth();ticketPeriod='month';render('dashboard')}})}const pdvSearch=document.getElementById('pdvSearch');if(pdvSearch){pdvSearch.oninput=e=>{pdvQuery=e.target.value;const position=pdvSearch.selectionStart;document.getElementById('content').innerHTML=pdvPage();bindPage();const next=document.getElementById('pdvSearch');next?.focus();next?.setSelectionRange(position,position)}}document.querySelectorAll('[data-row-edit]').forEach(row=>{const edit=()=>{const [t,id]=row.dataset.rowEdit.split(':');openForm(t,Number(id))};row.onclick=e=>{if(!e.target.closest('a,button,input,select'))edit()};row.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('a,button,input,select')){e.preventDefault();edit()}}});document.querySelectorAll('[data-flow-edit]').forEach(card=>{const edit=()=>{const [t,id]=card.dataset.flowEdit.split(':');openForm(t,Number(id))};card.onclick=e=>{if(!flowDragInProgress&&!e.target.closest('button'))edit()};card.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button')){e.preventDefault();edit()}};card.ondragstart=e=>{const [type,id]=card.dataset.flowEdit.split(':');draggedFlowItem={type,id:Number(id),origin:Number(card.dataset.flowOrigin)};flowDragInProgress=true;card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',card.dataset.flowEdit)};card.ondragend=()=>{card.classList.remove('dragging');document.querySelectorAll('.flow-column').forEach(x=>x.classList.remove('drag-over'));draggedFlowItem=null;setTimeout(()=>flowDragInProgress=false,0)}});document.querySelectorAll('[data-flow-stage]').forEach(column=>{column.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';column.classList.add('drag-over')};column.ondragleave=e=>{if(!column.contains(e.relatedTarget))column.classList.remove('drag-over')};column.ondrop=e=>{e.preventDefault();column.classList.remove('drag-over');if(draggedFlowItem)moveFlowItem(draggedFlowItem.type,draggedFlowItem.id,Number(column.dataset.flowStage))}});document.querySelectorAll('[data-advance]').forEach(x=>x.onclick=()=>advanceFlow(...x.dataset.advance.split(':')));document.querySelectorAll('[data-delete]').forEach(x=>x.onclick=()=>removeRecord(...x.dataset.delete.split(':')));document.querySelectorAll('[data-stock]').forEach(x=>x.onclick=()=>adjustStock(...x.dataset.stock.split(':')));document.querySelectorAll('[data-page-link]').forEach(x=>x.onclick=()=>render(x.dataset.pageLink));document.querySelectorAll('[data-reset]').forEach(x=>x.onclick=resetData);document.querySelectorAll('[data-pay-invoice]').forEach(x=>x.onclick=()=>payInvoice(Number(x.dataset.payInvoice)));document.getElementById('notificationSettings')?.addEventListener('submit',saveNotificationSettings);const storeSearch=document.getElementById('storeSearch');if(storeSearch)storeSearch.oninput=e=>{flowSearch=e.target.value;refreshFlowSearch()};document.querySelector('[data-clear-store]')?.addEventListener('click',()=>{flowSearch='';refreshFlowSearch()});const search=document.getElementById('tableSearch');if(search)search.oninput=e=>{filterState.query=e.target.value;refreshTableKeepingFocus()};const statusFilter=document.getElementById('statusFilter');if(statusFilter)statusFilter.onchange=e=>{filterState.status=e.target.value;refreshTableKeepingFocus()};const order=document.getElementById('orderFilter');if(order)order.onchange=e=>{filterState.order=e.target.value;refreshTableKeepingFocus()}}
function refreshFlowSearch(){const input=document.getElementById('storeSearch');const position=input?.selectionStart;document.getElementById('content').innerHTML=commercialFlow();bindPage();const next=document.getElementById('storeSearch');next?.focus();next?.setSelectionRange(position,position)}
function refreshQuotesKeepingFocus(){const input=document.getElementById('quoteIdFilter');const position=input?.selectionStart;document.getElementById('content').innerHTML=openQuotesPage();bindPage();const next=document.getElementById('quoteIdFilter');next?.focus();next?.setSelectionRange(position,position)}
function mountFilteredTotal(){if(document.querySelector('.filtered-total-card'))return;const quoteTable=document.querySelector('.quote-list-card');if(quoteTable){const total=quoteTable.querySelector('.summary-strip span:nth-child(2) strong')?.textContent||'R$ 0,00';quoteTable.insertAdjacentHTML('beforebegin',`<div class="filtered-total-card"><div><small>VALOR TOTAL DOS ORÇAMENTOS FILTRADOS</small><strong>${total}</strong></div><span>Calculado com base nos filtros selecionados</span></div>`);return}if(!['pedidos','faturados','enviados'].includes(currentPage))return;const subset=currentPage==='faturados'?x=>x.status==='Faturado':currentPage==='enviados'?x=>x.status!=='Enviado':null;const rows=filtered('pedidos',subset);const total=rows.reduce((sum,row)=>sum+Number(row.valor||0),0);const table=document.querySelector('.table-card');if(table)table.insertAdjacentHTML('beforebegin',`<div class="filtered-total-card"><div><small>VALOR TOTAL DOS PEDIDOS FILTRADOS</small><strong>${money(total)}</strong></div><span>${rows.length} registro(s) considerados</span></div>`)}
const contentObserver=new MutationObserver(()=>mountFilteredTotal());contentObserver.observe(document.getElementById('content'),{childList:true});
function refreshTableKeepingFocus(){const previous=document.getElementById('tableSearch');const wasSearchFocused=document.activeElement===previous;const position=previous?.selectionStart;document.getElementById('content').innerHTML=currentPage==='faturados'?orderSubset('Faturado'):currentPage==='enviados'?shippingPage():listing(currentPage);bindPage();const search=document.getElementById('tableSearch');if(search&&wasSearchFocused){search.focus();search.setSelectionRange(position,position)}}
function openForm(type,id=null){const config=configs[type];if(!config)return;const record=id?db[type].find(x=>x.id===id):null;editContext={type,id};document.getElementById('modalTitle').textContent=id?`Editar ${config.title.toLowerCase().replace(/s$/,'')}`:config.action;document.getElementById('modalDescription').textContent='As alterações ficam salvas somente neste navegador.';document.getElementById('modalSubmit').textContent=id?'Salvar alterações':'Adicionar';document.getElementById('modalError').textContent='';document.getElementById('formFields').innerHTML=config.fields.map((f,i)=>fieldHtml(f,record?.[f.key]??(type==='produtos'&&f.key==='markup'&&!record?db.configuracoes.markupPadrao:null),i)).join('')+(type==='produtos'?'<div class="margin-preview" id="marginPreview"></div>':'');if(type==='produtos'){document.querySelector('[name="valorCompra"]').addEventListener('input',updateProductPricing);document.querySelector('[name="valorVenda"]').addEventListener('input',updateProductMarginPreview);document.querySelector('[name="markup"]').addEventListener('input',updateProductPricing);if(!record)updateProductPricing();else updateProductMarginPreview()}openModal()}
function updateProductPricing(){const purchase=Number(document.querySelector('[name="valorCompra"]')?.value||0);const markupField=document.querySelector('[name="markup"]');const saleField=document.querySelector('[name="valorVenda"]');const markup=markupField?.value===''?null:Number(markupField.value);if(markup!==null&&Number.isFinite(markup)&&purchase>0&&saleField){saleField.value=(purchase*(1+markup/100)).toFixed(2)}updateProductMarginPreview()}
function updateProductMarginPreview(){const purchase=Number(document.querySelector('[name="valorCompra"]')?.value||0);const sale=Number(document.querySelector('[name="valorVenda"]')?.value||0);const amount=sale-purchase;const percent=sale>0?amount/sale*100:0;const preview=document.getElementById('marginPreview');if(preview)preview.innerHTML=`<span>Margem bruta calculada</span><strong class="${amount<0?'negative':''}">${money(amount)} <small>(${percent.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})}%)</small></strong>`}
function fieldHtml(f,value,index){const required=f.required?'required':'';const safe=escapeHtml(value??'');const displayValue=f.key==='status'&&editContext?.type==='pedidos'?orderStatusLabel(value):value;let control;if(f.type==='select'){const options=f.source?db[f.source].map(x=>x.nome):f.options;control=`<select name="${f.key}" ${required}><option value="">Selecione</option>${options.map(x=>`<option value="${escapeHtml(x)}" ${x===displayValue?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select>`}else control=`<input name="${f.key}" type="${f.type}" value="${safe}" ${f.type==='number'?`${f.key==='estoque'?'':'min="0"'} step="0.01"`:''} ${required}>`;const help=f.key==='estoqueMinimo'?'<small class="field-help">Opcional. Deixe vazio para não receber alerta de estoque baixo.</small>':f.key==='markup'?'<small class="field-help">Opcional. Percentual aplicado sobre o valor de compra para sugerir o preço de venda.</small>':'';return `${index%2===0?'<div class="form-row">':''}<label>${f.label}${control}${help}</label>${index%2===1||index===configs[editContext?.type]?.fields.length-1?'</div>':''}`}
function submitForm(event){event.preventDefault();const {type,id}=editContext;const config=configs[type];const formData=new FormData(event.currentTarget);const record={};for(const f of config.fields){let value=formData.get(f.key)?.toString().trim();if(!value&&f.required){document.getElementById('modalError').textContent=`Preencha o campo “${f.label}”.`;event.currentTarget.elements[f.key].focus();return}if(f.type==='number')value=value===''?null:Number(value);record[f.key]=value}if(type==='pedidos')record.status=internalOrderStatus(record.status);if(type==='produtos'){record.status=record.estoque<0?'Estoque incorreto':record.estoque===0?'Sem estoque':record.estoqueMinimo!==null&&record.estoque<=record.estoqueMinimo?'Estoque baixo':record.status}if(type==='orcamentos')record.atualizadoEm=new Date().toISOString().slice(0,10);if(type==='pedidos'){record.editadoPor='Lucas Almeida';record.editadoEm=new Date().toISOString().slice(0,10)}checkpoint();if(id){const index=db[type].findIndex(x=>x.id===id);db[type][index]={...db[type][index],...record}}else{const nextId=['orcamentos','pedidos'].includes(type)?Math.max(1000,...db[type].map(x=>x.id))+1:Math.max(0,...db[type].map(x=>x.id))+1;db[type].unshift({id:nextId,...record})}saveData();closeModal();showToast(id?'Registro atualizado.':'Registro adicionado.');render(currentPage)}
function removeRecord(type,id){const record=db[type].find(x=>x.id===Number(id));if(!record)return;const label=record.nome||record.comprador||`#${record.id}`;if(!confirm(`Excluir “${label}”?\n\nEsta ação afeta apenas os dados locais do protótipo.`))return;checkpoint();db[type]=db[type].filter(x=>x.id!==Number(id));saveData();showToast('Registro removido.');render(currentPage)}
function adjustStock(type,id,delta){const product=db[type].find(x=>x.id===Number(id));checkpoint();product.estoque=Number(product.estoque)+Number(delta);product.status=product.estoque<0?'Estoque incorreto':product.estoque===0?'Sem estoque':product.estoqueMinimo!==null&&product.estoque<=product.estoqueMinimo?'Estoque baixo':'Ativo';saveData();showToast('Estoque atualizado.');refreshTableKeepingFocus();updateNotifications()}
function saveNotificationSettings(event){event.preventDefault();const data=new FormData(event.currentTarget);const markupValue=String(data.get('markupPadrao')||'').replace('%','').replace(',','.').trim();checkpoint();db.configuracoes={diasClienteSemCompra:Number(data.get('diasClienteSemCompra')),diasOrcamentoSemRetorno:Number(data.get('diasOrcamentoSemRetorno')),diasAntecedenciaFatura:Number(data.get('diasAntecedenciaFatura')),markupPadrao:markupValue===''?null:Number(markupValue),mensagemEmail:String(data.get('mensagemEmail')).trim(),mensagemWhatsApp:String(data.get('mensagemWhatsApp')).trim()};saveData();showToast('Configurações e mensagens salvas.');render('configuracoes')}
function payInvoice(id){checkpoint();const invoice=db.faturas.find(x=>x.id===id);if(!invoice){undoHistory.pop();return}invoice.paga=true;saveData();showToast('Fatura marcada como paga.');render('configuracoes')}
function advanceFlow(type,id,index){id=Number(id);index=Number(index);checkpoint();if(type==='orcamentos'){const quote=db.orcamentos.find(x=>x.id===id);if(!quote){undoHistory.pop();return}db.orcamentos=db.orcamentos.filter(x=>x.id!==id);db.pedidos.unshift({id:Math.max(1000,...db.pedidos.map(x=>x.id))+1,comprador:quote.comprador,emissao:new Date().toISOString().slice(0,10),valor:quote.valor,status:'A faturar'})}else{const order=db.pedidos.find(x=>x.id===id);if(!order){undoHistory.pop();return}order.status=index===1?'Faturado':'Enviado'}saveData();showToast(index===0?'Orçamento convertido em pedido.':'Registro avançado para a próxima etapa.');render('fluxo')}
function moveFlowItem(type,id,target){const statusByStage=['','A faturar','Faturado','Enviado'];if(type==='orcamentos'&&target===0)return;checkpoint();if(type==='pedidos'){const order=db.pedidos.find(x=>x.id===id);if(!order){undoHistory.pop();return}if(target===0){db.pedidos=db.pedidos.filter(x=>x.id!==id);db.orcamentos.unshift({id:Math.max(2000,...db.orcamentos.map(x=>x.id))+1,comprador:order.comprador,validade:new Date(Date.now()+7*86400000).toISOString().slice(0,10),valor:order.valor,status:'Rascunho'})}else order.status=statusByStage[target]}else{const quote=db.orcamentos.find(x=>x.id===id);if(!quote){undoHistory.pop();return}db.orcamentos=db.orcamentos.filter(x=>x.id!==id);db.pedidos.unshift({id:Math.max(1000,...db.pedidos.map(x=>x.id))+1,comprador:quote.comprador,emissao:new Date().toISOString().slice(0,10),valor:quote.valor,status:statusByStage[target]})}saveData();showToast(`Registro movido para ${['Orçamentos','Pedidos','Faturados','Enviados'][target]}.`);render('fluxo')}
function resetData(){if(!confirm('Restaurar todos os dados demonstrativos originais?'))return;checkpoint();db=clone(seed);saveData();showToast('Dados demonstrativos restaurados.');render(currentPage)}
function checkpoint(){undoHistory.push(clone(db));if(undoHistory.length>50)undoHistory.shift();redoHistory.length=0}
function undo(){if(!undoHistory.length){showToast('Nada para desfazer.');return}redoHistory.push(clone(db));db=undoHistory.pop();saveData();closeModal();showToast('Alteração desfeita.');render(currentPage)}
function redo(){if(!redoHistory.length){showToast('Nada para refazer.');return}undoHistory.push(clone(db));db=redoHistory.pop();saveData();closeModal();showToast('Alteração refeita.');render(currentPage)}
const modal=document.getElementById('modal');function openModal(){modal.hidden=false;document.body.style.overflow='hidden';setTimeout(()=>modal.querySelector('input,select')?.focus(),0)}function closeModal(){modal.hidden=true;document.body.style.overflow='';editContext=null}function showToast(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2200)}
const userMenuButton=document.getElementById('userMenuButton');const userDropdown=document.getElementById('userDropdown');const forceRefreshButton=document.getElementById('forceRefreshButton');userMenuButton.onclick=e=>{e.stopPropagation();userDropdown.hidden=!userDropdown.hidden;userMenuButton.setAttribute('aria-expanded',String(!userDropdown.hidden))};document.addEventListener('click',e=>{if(!e.target.closest('.user-menu')){userDropdown.hidden=true;userMenuButton.setAttribute('aria-expanded','false')}});forceRefreshButton.onclick=forceRefresh;async function forceRefresh(){forceRefreshButton.disabled=true;forceRefreshButton.classList.add('loading');forceRefreshButton.querySelector('strong').textContent='Atualizando...';showToast('Limpando cache e buscando a versão mais recente.');try{if('caches'in window){const keys=await caches.keys();await Promise.all(keys.map(key=>caches.delete(key)))}if('serviceWorker'in navigator){const registrations=await navigator.serviceWorker.getRegistrations();await Promise.all(registrations.map(registration=>registration.unregister()))}}finally{const version=Date.now();document.querySelectorAll('script[src],link[rel="stylesheet"][href]').forEach(resource=>{const url=new URL(resource.src||resource.href,location.href);url.searchParams.set('refresh',version);if(resource.src)resource.src=url.href;else resource.href=url.href});const url=new URL(location.href);url.searchParams.set('refresh',version);location.replace(url.href)}}
document.addEventListener('change',e=>{if(e.target.id==='quoteDaysFilter'){quoteFilters.days=e.target.value;render('orcamentos')}if(e.target.id==='quoteCompanyFilter'){quoteFilters.company=e.target.value;render('orcamentos')}});document.addEventListener('input',e=>{if(e.target.id==='quoteIdFilter'){quoteFilters.id=e.target.value;refreshQuotesKeepingFocus()}});
document.addEventListener('change',e=>{if(e.target.id==='dateFromFilter'||e.target.id==='dateToFilter'){filterState.dateFrom=document.getElementById('dateFromFilter')?.value||'';filterState.dateTo=document.getElementById('dateToFilter')?.value||'';refreshTableKeepingFocus()}});
document.addEventListener('click',e=>{const stage=e.target.closest('[data-dashboard-stage]');if(stage){dashboardStage=Number(stage.dataset.dashboardStage);render('dashboard',{preserveScroll:true});return}if(e.target.closest('[data-clear-stage]')){dashboardStage=null;render('dashboard');return}const order=e.target.closest('[data-stage-order]');if(order)openForm('pedidos',Number(order.dataset.stageOrder))});
document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>render(x.dataset.page));document.getElementById('menuButton').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.getElementById('modalClose').onclick=closeModal;document.getElementById('modalCancel').onclick=closeModal;document.getElementById('recordForm').onsubmit=submitForm;modal.onclick=e=>{if(e.target===modal)closeModal()};const notificationButtons=document.getElementById('notificationButtons');const notificationPanel=document.getElementById('notificationPanel');notificationButtons.onclick=e=>{e.stopPropagation();const button=e.target.closest('[data-notification-category]');if(!button)return;const same=activeNotificationCategory===button.dataset.notificationCategory;activeNotificationCategory=button.dataset.notificationCategory;const shouldClose=same&&!notificationPanel.hidden;updateNotifications();notificationPanel.hidden=shouldClose};notificationPanel.onclick=e=>{e.stopPropagation();if(e.target.closest('[data-read-all]')){getNotifications().filter(x=>notificationCategory(x)===activeNotificationCategory).forEach(x=>notificationRead.add(x.id));persistNotificationRead();updateNotifications();return}const footer=e.target.closest('[data-page-notifications]');if(footer){notificationPanel.hidden=true;render(footer.dataset.pageNotifications);return}const item=e.target.closest('[data-alert-id]');if(!item)return;notificationRead.add(item.dataset.alertId);persistNotificationRead();updateNotifications();if(e.target.closest('a,summary,details'))return;if(item.dataset.alertRoute){notificationPanel.hidden=true;if(item.dataset.alertStore)flowSearch=item.dataset.alertStore;render(item.dataset.alertRoute)}};document.addEventListener('click',e=>{if(!e.target.closest('.notification-center'))notificationPanel.hidden=true});document.onkeydown=e=>{if(e.key==='Escape'){closeModal();notificationPanel.hidden=true;return}const typing=e.target.matches?.('input,textarea,select,[contenteditable="true"]');if(typing)return;if(e.ctrlKey&&!e.shiftKey&&e.key.toLowerCase()==='z'){e.preventDefault();undo()}else if(e.ctrlKey&&(e.key.toLowerCase()==='y'||(e.shiftKey&&e.key.toLowerCase()==='z'))){e.preventDefault();redo()}};function persistNotificationRead(){localStorage.setItem(NOTIFICATION_READ_KEY,JSON.stringify([...notificationRead]))}render();
